// #70ef78 (30e340e0fefb146bba70ef78) — текст «פרקי אבות» вне сезона, исправлен commit f881957, עבר QA 26.10.2026 (iPhone + веб).
// Было: «…הסימון יחזור בשבת הראשונה שאחרי פסח.», а метка «פרק השבוע» появлялась уже в будни перед этой שבת (29.4.2027).
// Стало: «…הסימון יחזור בשבוע של השבת הראשונה שאחרי פסח.»; правило (глава ближайшей שבת всю неделю) не менялось.
// מה רצוי: тикет («הטקסט… לא סותר את מה שהאפליקציה עושה… הכלל עצמו נשאר») + коммент программиста 25.10 16:22 + решение пользователя 25.10.
// Факты проверенного прогона 26.10 (скрипт подмены дат scratchpad 70ef78/run.js, скрины .qa/screenshots/70ef78-2027-*.png):
// 24.4.2027 09:00 и 2.10.2027 — новый текст, меток нет; 25.4, 29.4, 1.5.2027 — «פרק השבוע: פרקי אבות א׳.», метка только на א׳;
// 18.9.2027 — «…ג׳–ד׳.», метки на обеих. Подмена часов с сохранением сессии — ../_helpers/clock.ts (как th-05);
// файл .qa/auth/user1.json не меняется (контекст браузера у теста свой). Нужна живая сессия user1 (`npm run qa-login`).
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { setFixedTimeKeepingSession } from '../_helpers/clock';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const OFF_SEASON = 'פרקי אבות נאמרים בשבתות שמפסח עד ראש השנה, ולכן עכשיו אין «פרק השבוע». הסימון יחזור בשבוע של השבת הראשונה שאחרי פסח.';
const OLD_RETURN = 'הסימון יחזור בשבת הראשונה שאחרי פסח';

/** Дата и время (Израиль, +03:00) → ожидаемые главы с меткой; [] — вне сезона (новый текст). */
const CASES: { at: string; what: string; chapters: string[] }[] = [
  { at: '2027-04-24T09:00', what: 'שבת חוה״מ פסח — вне сезона', chapters: [] },
  { at: '2027-04-25T12:00', what: 'вс, неделя первой שבת после פסח', chapters: ['א׳'] },
  { at: '2027-04-29T12:00', what: 'чт перед первой שבת после פסח', chapters: ['א׳'] },
  { at: '2027-05-01T09:00', what: 'первая שבת после פסח', chapters: ['א׳'] },
  { at: '2027-09-18T09:00', what: 'ט״ז אלול, сдвоенная', chapters: ['ג׳', 'ד׳'] },
  { at: '2027-10-02T09:00', what: 'ראש השנה — вне сезона', chapters: [] },
];

/** Открыть «פרקי אבות» на /tehilim и дождаться строки недели или текста вне сезона (переключение сегмента = пересчёт). */
async function openAvot(page: Page) {
  await page.goto('/tehilim');
  const avot = page.getByRole('button', { name: 'פרקי אבות', exact: true });
  await expect(avot).toBeVisible({ timeout: 15_000 });
  await page.getByRole('button', { name: 'תהילים', exact: true }).click();
  await avot.click();
  await expect(page.locator('#tehilim-avot-week, #tehilim-avot-off-season').first()).toBeVisible({ timeout: 10_000 });
}
/** Буквы глав с меткой «פרק השבוע» (aria-label «פרקי אבות X — <начало> — פרק השבוע»). */
async function markedChapters(page: Page): Promise<string[]> {
  return page.locator('[aria-label^="פרקי אבות "]').evaluateAll((els) =>
    els.map((e) => e.getAttribute('aria-label') ?? '').filter((l) => /— פרק השבוע$/.test(l)).map((l) => l.split(' ')[2]));
}

test.describe('פרקי אבות — текст вне сезона и неделя первой שבת после פסח (#70ef78)', () => {
  for (const c of CASES) {
    const want = c.chapters.length ? `«פרק השבוע: פרקי אבות ${c.chapters.join('–')}.»` : 'новый текст вне сезона, меток нет';
    test(`TH-05b ${c.at.replace('T', ' ')} (${c.what}) → ${want} #70ef78 #30e340e0 @iphone @prod-safe`, async ({ page }) => {
      await setFixedTimeKeepingSession(page, new Date(`${c.at}:00+03:00`));
      await openAvot(page);
      await expect(page.getByText(/בואו נתחיל|מספר נייד/)).toHaveCount(0);   // не разлогинило

      if (c.chapters.length) {
        await expect(page.locator('#tehilim-avot-week')).toHaveText(`פרק השבוע: פרקי אבות ${c.chapters.join('–')}.`);
        await expect(page.locator('#tehilim-avot-off-season')).toHaveCount(0);
        await expect.poll(() => markedChapters(page)).toEqual(c.chapters);
      } else {
        await expect(page.locator('#tehilim-avot-off-season')).toHaveText(OFF_SEASON);
        await expect(page.getByText(OLD_RETURN)).toHaveCount(0);
        await expect(page.locator('#tehilim-avot-week')).toHaveCount(0);
        await expect.poll(() => markedChapters(page)).toEqual([]);
      }
      await expect(page.locator('[aria-label^="פרקי אבות "]')).toHaveCount(6);
    });
  }
});
